        r_0 = ra_4 * r_0
        r_1 = ra_4 * r_1
        r_2 = ra_4 * r_2
        r_3 = ra_4
        pp_0 = retain_t * pp_0 + rebuild_lam_4 * r_0
        pp_1 = retain_t * pp_1 + rebuild_lam_4 * r_1
        pp_2 = retain_t * pp_2 + rebuild_lam_4 * r_2
        pp_3 = retain_t * pp_3 + rebuild_lam_4 * r_3
