    dc_1 = tl.load(DCAUSAL + qbase + 49).to(tl.float32)
    dc_2 = tl.load(DCAUSAL + qbase + 50).to(tl.float32)
    dc_3 = tl.load(DCAUSAL + qbase + 51).to(tl.float32)
