    dm_1 = tl.load(DMATRIX + qbase + 49).to(tl.float32)
    dm_2 = tl.load(DMATRIX + qbase + 50).to(tl.float32)
    bndp = zero
    # rebuild P^(0) from P^(-1)
    if RELOAD:
        rebuild_lam_0 = tl.load(LAM + lbase + 0 * SL1, mask=key_mask, other=0.0, volatile=True).to(tl.float32)
