    if PRODUCT:
        ra_0 = tl.exp(tl.load(G + dbase + 0 * SD1, mask=key_mask, other=0.0, volatile=True).to(tl.float32))
        ap = ra_0
        bndp = retain_t * bndp + rebuild_lam_0 * ap
    if RELOAD:
        pp_0 = zero + rebuild_lam_0
    if not RELOAD:
        retain_t = 1.0 - lam_0
        bndp = retain_t * bndp + lam_0 * tl.exp(G_0)
