    if PRODUCT:
        ra_1 = tl.exp(tl.load(G + dbase + 1 * SD1, mask=key_mask, other=0.0, volatile=True).to(tl.float32))
        ap = ap * ra_1
        bndp = retain_t * bndp + rebuild_lam_1 * ap
        r_0 = ra_1
        pp_0 = retain_t * pp_0 + rebuild_lam_1 * r_0
    if RELOAD:
        pp_1 = zero + rebuild_lam_1
    if not RELOAD:
        pp_0 = retain_t * pp_0 + lam_1 * x_0
        pp_1 = zero + lam_1
    # rebuild P^(2) from P^(1)
    if RELOAD:
        rebuild_lam_2 = tl.load(LAM + lbase + 2 * SL1, mask=key_mask, other=0.0, volatile=True).to(tl.float32)
        retain_t = 1.0 - rebuild_lam_2
    if RELOAD and not PRODUCT:
        bndp = retain_t * bndp + rebuild_lam_2 * tl.exp(G_2)
    if not RELOAD:
        retain_t = 1.0 - lam_2
        bndp = retain_t * bndp + lam_2 * tl.exp(G_2)
    if not PRODUCT:
        x_0 = tl.exp(tl.minimum(G_2 - G_0, 0.0))
        x_1 = tl.exp(tl.minimum(G_2 - G_1, 0.0))
    if RELOAD and not PRODUCT:
        pp_0 = retain_t * pp_0 + rebuild_lam_2 * x_0
        pp_1 = retain_t * pp_1 + rebuild_lam_2 * x_1
    if PRODUCT:
        ra_2 = tl.exp(tl.load(G + dbase + 2 * SD1, mask=key_mask, other=0.0, volatile=True).to(tl.float32))
        ap = ap * ra_2
        bndp = retain_t * bndp + rebuild_lam_2 * ap
        r_0 = ra_2 * r_0
        r_1 = ra_2
        pp_0 = retain_t * pp_0 + rebuild_lam_2 * r_0
        pp_1 = retain_t * pp_1 + rebuild_lam_2 * r_1
    if RELOAD:
        pp_2 = zero + rebuild_lam_2
    if not RELOAD:
        pp_0 = retain_t * pp_0 + lam_2 * x_0
        pp_1 = retain_t * pp_1 + lam_2 * x_1
        pp_2 = zero + lam_2
    if not PRODUCT:
        e_0 = tl.exp(tl.minimum(G_3 - G_0, 0.0))
