    dbnd_i = dq1_i * qs
    QB = dbnd_i + (1.0 - lam_4) * QB
    dkeep_i = dq2_i * qs
    ql = dkeep_i + (1.0 - lam_4) * ql
    dlam_vec = qp_0 * (e_0 - pp_0) + qp_1 * (e_1 - pp_1) + qp_2 * (e_2 - pp_2) + qp_3 + QB * (a_i - bndp)
    tl.store(DLAM + base + 3 * H * K, dlam_vec - keep_2 * ql, mask=key_mask)
    de_0 = dc_0 * qa * k_0 + dm_0 * er * k_0 + lam_3 * qp_0
