    de_2 = dc_2 * qa * k_2 + dm_2 * er * k_2 + lam_3 * qp_2
    dA = dabar_i * er + dq1_i * qa + lam_3 * QB
    dG_i = de_0 * e_0 + de_1 * e_1 + de_2 * e_2 + dA * a_i - dgc_3
