    dgc_1 += de_1 * e_1
    dgc_2 += de_2 * e_2
    dq_i = dq1_i * (gm_i * a_i + (1.0 - gm_i) * bnd_i) + dq2_i * (1.0 - gm_i) * keep_3 + dc_0 * k_0 * (gm_i * e_0 + (1.0 - gm_i) * pi_0) + dc_1 * k_1 * (gm_i * e_1 + (1.0 - gm_i) * pi_1) + dc_2 * k_2 * (gm_i * e_2 + (1.0 - gm_i) * pi_2) + dc_3 * k_3 * (gm_i + (1.0 - gm_i) * pi_3)
    dgm_i = q_i * (dq1_i * (a_i - bnd_i) - dq2_i * keep_3 + dc_0 * k_0 * (e_0 - pi_0) + dc_1 * k_1 * (e_1 - pi_1) + dc_2 * k_2 * (e_2 - pi_2) + dc_3 * k_3 * (1.0 - pi_3))
    inter_k = dabar_i * a_i + dm_0 * k_0 * e_0 + dm_1 * k_1 * e_1 + dm_2 * k_2 * e_2
    tl.store(DQ + base + 3 * H * K, (dq_i * SCALE).to(DQ.dtype.element_ty), mask=key_mask)
