    dq_i = dq1_i * (gm_i * a_i + (1.0 - gm_i) * bnd_i) + dq2_i * (1.0 - gm_i) * keep_2 + dc_0 * k_0 * (gm_i * e_0 + (1.0 - gm_i) * pi_0) + dc_1 * k_1 * (gm_i * e_1 + (1.0 - gm_i) * pi_1) + dc_2 * k_2 * (gm_i + (1.0 - gm_i) * pi_2)
